import { useState, useEffect } from "react";

/* ── Bengali helpers ── */
const BN = ["০","১","২","৩","৪","৫","৬","৭","৮","৯"];
const toBn = (n) => String(n).replace(/[0-9]/g, d => BN[+d]);
const toEn = (s) => String(s).replace(/[০-৯]/g, d => BN.indexOf(d));
const BN_MONTHS = ["জানুয়ারি","ফেব্রুয়ারি","মার্চ","এপ্রিল","মে","জুন","জুলাই","আগস্ট","সেপ্টেম্বর","অক্টোবর","নভেম্বর","ডিসেম্বর"];
const fmtDate = (s) => {
  if (!s) return "";
  const [y,m,d] = s.split("-");
  return `${toBn(parseInt(d))} ${BN_MONTHS[+m-1]} ${toBn(y)}`;
};
const todayStr = () => new Date().toISOString().split("T")[0];

/* ── Data model ── */
const STATIONS = [
  { id:1, name:"" },
  { id:2, name:"নাসিম ফিলিং স্টেশন, দত্তনগর রোড, জীবননগর, চুয়াডাঙ্গা" },
  { id:3, name:"পিয়াস ফিলিং স্টেশন, দেহাটি জীবননগর, চুয়াডাঙ্গা" },
  { id:4, name:"উৎসব ফিলিং স্টেশন, লক্ষীপুর জীবননগর, চুয়াডাঙ্গা" },
  { id:5, name:"অংগন ফিলিং স্টেশন, সন্তোষপুর জীবননগর, চুয়াডাঙ্গা" },
  { id:6, name:"মেসার্স লিমা ফিলিং স্টেশন, হাসাদাহ জীবননগর" },
];
const FUELS     = ["diesel","petrol","octane"];
const FUEL_LBL  = { diesel:"ডিজেল", petrol:"পেট্রোল", octane:"অকটেন" };
const FIELDS    = ["prev","received","closing"];
const FIELD_LBL = { prev:"পূর্বের মজুদ(লিঃ)", received:"ডিপো হতে গ্রহণ (লিঃ)", closing:"সমাপনী মজুদ(লিঃ)" };

const emptyRow  = () => ({ diesel:{prev:"",received:"",closing:""}, petrol:{prev:"",received:"",closing:""}, octane:{prev:"",received:"",closing:""} });
const emptyData = () => STATIONS.map(s => ({ stationId:s.id, ...emptyRow() }));

const STORE_KEY = "fuel_report_v2";
const loadAll   = async () => { try { const r = await window.storage.get(STORE_KEY); return r ? JSON.parse(r.value) : {}; } catch { return {}; } };
const saveAll   = async (d) => { try { await window.storage.set(STORE_KEY, JSON.stringify(d)); } catch(e) { console.error(e); } };

const calcTotal = (rows, fuel, field) => {
  const s = rows.reduce((a,r) => { const n=parseInt(toEn(r[fuel][field])); return a+(isNaN(n)?0:n); },0);
  return s > 0 ? toBn(s) : "-";
};

/* ── Load external script ── */
const loadScript = (src) => new Promise((res,rej) => {
  if (document.querySelector(`script[src="${src}"]`)) { res(); return; }
  const s = document.createElement("script"); s.src=src; s.onload=res; s.onerror=rej; document.head.appendChild(s);
});

/* ══════════════════════════════════════
   DOCX generator — black & white, Nikosh
══════════════════════════════════════ */
async function downloadDocx(dateStr, rows) {
  await loadScript("https://cdnjs.cloudflare.com/ajax/libs/docx/8.5.0/docx.umd.min.js");
  const {
    Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
    AlignmentType, WidthType, BorderStyle, VerticalAlign, PageOrientation
  } = window.docx;

  const bdr     = { style:BorderStyle.SINGLE, size:4, color:"000000" };
  const borders = { top:bdr, bottom:bdr, left:bdr, right:bdr };
  const FONT    = "Nikosh";

  const mkCell = (text, {rowSpan,colSpan,bold,sz=18,align="center",shade}={}) =>
    new TableCell({
      borders, verticalAlign:VerticalAlign.CENTER,
      rowSpan, columnSpan:colSpan,
      // header rows get light grey shade
      shading: shade ? { fill:shade, type:"clear", color:"auto" } : undefined,
      margins:{ top:60,bottom:60,left:90,right:90 },
      children:[new Paragraph({
        alignment: align==="left" ? AlignmentType.LEFT : AlignmentType.CENTER,
        children:[new TextRun({ text:String(text), font:FONT, size:sz, bold:!!bold })]
      })]
    });

  const totals = {};
  FUELS.forEach(f=>{totals[f]={};FIELDS.forEach(fi=>{totals[f][fi]=calcTotal(rows,f,fi);});});

  const table = new Table({
    width:{ size:13500, type:WidthType.DXA },
    rows:[
      // Header row 1
      new TableRow({ children:[
        mkCell("ক্রঃনং",            {rowSpan:2, bold:true, sz:18, shade:"BBBBBB"}),
        mkCell("উপজেলা",            {rowSpan:2, bold:true, sz:18, shade:"BBBBBB"}),
        mkCell("প্রতিষ্ঠানের নাম",  {rowSpan:2, bold:true, sz:18, shade:"BBBBBB"}),
        ...FUELS.map(f=>mkCell(FUEL_LBL[f], {colSpan:3, bold:true, sz:18, shade:"BBBBBB"}))
      ]}),
      // Header row 2
      new TableRow({ children:[
        ...FUELS.flatMap(()=>FIELDS.map(fi=>mkCell(FIELD_LBL[fi], {sz:15, shade:"BBBBBB"})))
      ]}),
      // Data rows
      ...STATIONS.map((s,i)=>new TableRow({ children:[
        mkCell(toBn(String(i+1).padStart(2,"0")), {sz:18}),
        mkCell(i===0?"জীবননগর":"", {sz:18}),
        new TableCell({ borders, margins:{top:60,bottom:60,left:90,right:90},
          children:[new Paragraph({ alignment:AlignmentType.LEFT,
            children:[new TextRun({text:s.name, font:FONT, size:16})] })]
        }),
        ...FUELS.flatMap(f=>FIELDS.map(fi=>mkCell(rows[i][f][fi]||"-", {sz:18})))
      ]})),
      // Total row
      new TableRow({ children:[
        new TableCell({ borders, columnSpan:3, shading:{fill:"BBBBBB",type:"clear",color:"auto"},
          margins:{top:60,bottom:60,left:90,right:90},
          children:[new Paragraph({alignment:AlignmentType.CENTER,
            children:[new TextRun({text:"সর্বমোট", font:FONT, size:18, bold:true})]})]
        }),
        ...FUELS.flatMap(f=>FIELDS.map(fi=>mkCell(totals[f][fi], {bold:true, sz:18})))
      ]})
    ]
  });

  const run  = (text,sz=22,bold=false) => new TextRun({text, font:FONT, size:sz, bold});
  const para = (children, align=AlignmentType.CENTER, spacingBefore=0, spacingAfter=0) =>
    new Paragraph({alignment:align, spacing:{before:spacingBefore,after:spacingAfter}, children});

  const doc = new Document({
    sections:[{
      properties:{ page:{
        size:{ width:15120, height:12240, orientation:PageOrientation.LANDSCAPE },
        margin:{ top:720, right:720, bottom:720, left:720 }
      }},
      children:[
        para([run("উপজেলা: জীবননগর", 28, true)],           AlignmentType.CENTER, 0,  80),
        para([run("জ্বালানী তেলের দৈনিক রিপোর্ট", 26, true)], AlignmentType.CENTER, 0,  80),
        para([run(`তারিখ: ${fmtDate(dateStr)}`, 22)],        AlignmentType.CENTER, 0, 200),
        table,
		para([run("স্বাক্ষরিত", 20)], AlignmentType.RIGHT, 600, 60),
        para([run("উপজেলা নির্বাহী অফিসার", 20)], AlignmentType.RIGHT, 600, 60),
        para([run("জীবননগর, চুয়াডাঙ্গা।", 20)],            AlignmentType.RIGHT),
      ]
    }]
  });

  const blob = await Packer.toBlob(doc);
  const url  = URL.createObjectURL(blob);
  Object.assign(document.createElement("a"),{href:url,download:`fuel_report_${dateStr}.docx`}).click();
  URL.revokeObjectURL(url);
}

/* ══════════════════════════════════════
   PDF generator — B&W, Nikosh via html2canvas
══════════════════════════════════════ */
async function downloadPdf(dateStr, rows) {
  await loadScript("https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js");
  await loadScript("https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js");

  const { jsPDF } = window.jspdf;
  const totals = {};
  FUELS.forEach(f=>{totals[f]={};FIELDS.forEach(fi=>{totals[f][fi]=calcTotal(rows,f,fi);});});

  const wrapper = document.createElement("div");
  wrapper.style.cssText = "position:fixed;left:-9999px;top:0;width:1120px;background:#fff;padding:28px 32px;font-family:'Nikosh',sans-serif;color:#000;";

  wrapper.innerHTML = `
    <div style="text-align:center;margin-bottom:8px;font-family:'Nikosh',sans-serif">
      <div style="font-size:20px;font-weight:800;color:#000">উপজেলা: জীবননগর</div>
      <div style="font-size:17px;font-weight:700;margin-top:5px;color:#000">জ্বালানী তেলের দৈনিক রিপোর্ট</div>
      <div style="font-size:15px;margin-top:5px;color:#000">তারিখ: ${fmtDate(dateStr)}</div>
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;margin-top:12px;font-family:'Nikosh',sans-serif;color:#000">
      <thead>
        <tr>
          <th rowspan="2" style="border:1px solid #000;padding:6px 4px;background:#bbb;font-weight:700;text-align:center;color:#000">ক্রঃনং</th>
          <th rowspan="2" style="border:1px solid #000;padding:6px 4px;background:#bbb;font-weight:700;text-align:center;color:#000">উপজেলা</th>
          <th rowspan="2" style="border:1px solid #000;padding:6px 4px;background:#bbb;font-weight:700;text-align:center;min-width:160px;color:#000">প্রতিষ্ঠানের নাম</th>
          ${FUELS.map(f=>`<th colspan="3" style="border:1px solid #000;padding:6px 4px;background:#bbb;font-weight:700;text-align:center;color:#000">${FUEL_LBL[f]}</th>`).join("")}
        </tr>
        <tr>
          ${FUELS.map(()=>FIELDS.map(fi=>`<th style="border:1px solid #000;padding:5px 3px;background:#ddd;font-size:10px;text-align:center;color:#000">${FIELD_LBL[fi]}</th>`).join("")).join("")}
        </tr>
      </thead>
      <tbody>
        ${STATIONS.map((s,i)=>`
          <tr style="background:#fff">
            <td style="border:1px solid #000;padding:5px 4px;text-align:center;color:#000">${toBn(String(i+1).padStart(2,"0"))}</td>
            <td style="border:1px solid #000;padding:5px 4px;text-align:center;color:#000">${i===0?"জীবননগর":""}</td>
            <td style="border:1px solid #000;padding:5px 4px;font-size:11px;color:#000">${s.name}</td>
            ${FUELS.map(f=>FIELDS.map(fi=>`<td style="border:1px solid #000;padding:5px 4px;text-align:center;color:#000">${rows[i][f][fi]||"-"}</td>`).join("")).join("")}
          </tr>
        `).join("")}
        <tr style="background:#bbb">
          <td colspan="3" style="border:1px solid #000;padding:6px 4px;text-align:center;font-weight:800;color:#000">সর্বমোট</td>
          ${FUELS.map(f=>FIELDS.map(fi=>`<td style="border:1px solid #000;padding:5px 4px;text-align:center;font-weight:700;color:#000">${totals[f][fi]}</td>`).join("")).join("")}
        </tr>
      </tbody>
    </table>
    <div style="text-align:right;margin-top:50px;padding-right:20px;font-size:14px;font-family:'Nikosh',sans-serif;color:#000;line-height:1.9">
      স্বাক্ষরিত উপজেলা নির্বাহী অফিসার<br/>জীবননগর, চুয়াডাঙ্গা।
    </div>
  `;

  document.body.appendChild(wrapper);
  if (document.fonts && document.fonts.ready) await document.fonts.ready;
  await new Promise(r => setTimeout(r, 300));

  const canvas = await window.html2canvas(wrapper, { scale:2, useCORS:true, backgroundColor:"#ffffff" });
  document.body.removeChild(wrapper);

  const imgData = canvas.toDataURL("image/png");
  const pdf     = new jsPDF({ orientation:"landscape", unit:"mm", format:"a4" });
  const pW      = pdf.internal.pageSize.getWidth();
  const pH      = pdf.internal.pageSize.getHeight();
  const finalW  = pW - 10;
  const finalH  = (canvas.height / canvas.width) * finalW;

  pdf.addImage(imgData, "PNG", 5, 5, finalW, Math.min(finalH, pH-10));
  pdf.save(`fuel_report_${dateStr}.pdf`);
}

/* ══════════════════════════
   Main App
══════════════════════════ */
export default function App() {
  const [view,setView]         = useState("entry");
  const [allData,setAllData]   = useState({});
  const [selDate,setSelDate]   = useState(todayStr());
  const [rows,setRows]         = useState(emptyData());
  const [loaded,setLoaded]     = useState(false);
  const [savedDates,setSaved]  = useState([]);
  const [histDate,setHistDate] = useState("");
  const [histRows,setHistRows] = useState(null);
  const [msg,setMsg]           = useState("");
  const [dlState,setDlState]   = useState("");

  useEffect(()=>{ loadAll().then(all=>{ setAllData(all); setSaved(Object.keys(all).sort().reverse()); setLoaded(true); }); },[]);

  useEffect(()=>{
    if(!loaded) return;
    if(allData[selDate]){ setRows(allData[selDate]); return; }
    const prev = Object.keys(allData).filter(d=>d<selDate).sort().reverse()[0];
    if(prev){
      setRows(allData[prev].map(r=>({
        stationId:r.stationId,
        diesel:{prev:r.diesel.closing,received:"",closing:""},
        petrol:{prev:r.petrol.closing,received:"",closing:""},
        octane:{prev:r.octane.closing,received:"",closing:""},
      })));
    } else { setRows(emptyData()); }
  },[selDate,loaded]);

  const setCell=(ri,f,fi,v)=>setRows(rs=>rs.map((r,i)=>i!==ri?r:{...r,[f]:{...r[f],[fi]:v}}));
  const flash=(m)=>{setMsg(m);setTimeout(()=>setMsg(""),2500);};

  const handleSave=async()=>{
    const updated={...allData,[selDate]:rows};
    setAllData(updated); setSaved(Object.keys(updated).sort().reverse());
    await saveAll(updated); flash("✓ সংরক্ষিত হয়েছে!");
  };

  const handleDl=async(type,date,rowsArr)=>{
    const key=date+"_"+type; setDlState(key);
    try{
      if(type==="docx") await downloadDocx(date,rowsArr);
      else              await downloadPdf(date,rowsArr);
    }catch(e){ console.error(e); alert("ডাউনলোড ব্যর্থ: "+e.message); }
    setDlState("");
  };

  const deleteDate=async(d)=>{
    if(!window.confirm("এই তারিখের তথ্য মুছে ফেলবেন?")) return;
    const u={...allData}; delete u[d]; setAllData(u); setSaved(Object.keys(u).sort().reverse());
    await saveAll(u); if(histDate===d){setHistDate("");setHistRows(null);}
  };

  /* ── Table cell styles — black & white ── */
  const TH_BASE = { border:"1px solid #000", padding:"5px 6px", fontWeight:700, textAlign:"center", fontSize:12, color:"#000" };
  const TH_HD   = { ...TH_BASE, background:"#bbb" };
  const TH_SUB  = { ...TH_BASE, background:"#ddd", fontSize:11 };
  const TD      = { border:"1px solid #000", padding:"3px 5px", verticalAlign:"middle", color:"#000" };

  /* ── Download button bar ── */
  const DlBar = ({date, rowsArr}) => (
    <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
      {[["docx","📄 DOCX ডাউনলোড"],["pdf","📕 PDF ডাউনলোড"]].map(([t,lbl])=>{
        const busy = dlState===date+"_"+t;
        return (
          <button key={t} onClick={()=>handleDl(t,date,rowsArr)} disabled={!!dlState}
            style={{background:busy?"#999":"#222",color:"#fff",border:"none",borderRadius:6,padding:"7px 16px",cursor:busy?"not-allowed":"pointer",fontWeight:700,fontSize:13,fontFamily:"'Nikosh',sans-serif"}}>
            {busy?"⏳ তৈরি হচ্ছে...":lbl}
          </button>
        );
      })}
    </div>
  );

  /* ── Report table — black & white ── */
  const ReportTable = ({rowsArr, editable}) => (
    <div style={{overflowX:"auto"}}>
      <table style={{borderCollapse:"collapse",width:"100%",minWidth:960,background:"#fff",border:"1px solid #000"}}>
        <thead>
          <tr>
            <th rowSpan={2} style={TH_HD}>ক্রঃনং</th>
            <th rowSpan={2} style={TH_HD}>উপজেলা</th>
            <th rowSpan={2} style={{...TH_HD,minWidth:170}}>প্রতিষ্ঠানের নাম</th>
            {FUELS.map(f=><th key={f} colSpan={3} style={TH_HD}>{FUEL_LBL[f]}</th>)}
          </tr>
          <tr>
            {FUELS.map(f=>FIELDS.map((fi,hi)=>(
              <th key={f+hi} style={TH_SUB}>{FIELD_LBL[fi]}</th>
            )))}
          </tr>
        </thead>
        <tbody>
          {STATIONS.map((s,i)=>(
            <tr key={s.id} style={{background:"#fff"}}>
              <td style={{...TD,textAlign:"center",fontWeight:600}}>{toBn(String(i+1).padStart(2,"0"))}</td>
              <td style={{...TD,textAlign:"center"}}>{i===0?"জীবননগর":""}</td>
              <td style={{...TD,fontSize:12}}>{s.name}</td>
              {FUELS.map(f=>FIELDS.map(fi=>(
                <td key={f+fi} style={{...TD,padding:editable?2:4}}>
                  {fi==="prev" ? (
                    <div style={{textAlign:"center",padding:"3px 7px",background:"#f0f0f0",borderRadius:3,color:"#000",fontWeight:600,fontSize:13}}>
                      {rowsArr[i][f][fi] || <span style={{color:"#aaa"}}>-</span>}
                    </div>
                  ) : editable ? (
                    <input value={rows[i][f][fi]} onChange={e=>setCell(i,f,fi,e.target.value)}
                      style={{width:"100%",border:fi==="closing"?"2px solid #000":"1px solid #888",borderRadius:3,padding:"4px 6px",textAlign:"center",fontSize:13,background:"#fff",boxSizing:"border-box",fontFamily:"'Nikosh',sans-serif",color:"#000"}}
                      placeholder="-"/>
                  ) : (
                    <div style={{textAlign:"center",fontSize:13}}>{rowsArr[i][f][fi]||"-"}</div>
                  )}
                </td>
              )))}
            </tr>
          ))}
          <tr style={{background:"#bbb"}}>
            <td colSpan={3} style={{...TD,fontWeight:800,textAlign:"center",background:"#bbb"}}>সর্বমোট</td>
            {FUELS.map(f=>FIELDS.map(fi=>(
              <td key={f+fi} style={{...TD,fontWeight:700,textAlign:"center",background:"#bbb"}}>
                {calcTotal(rowsArr,f,fi)}
              </td>
            )))}
          </tr>
        </tbody>
      </table>
    </div>
  );

  const Signature = () => (
    <div style={{textAlign:"right",marginTop:20,paddingRight:16,color:"#000",fontSize:14,lineHeight:"1.9"}}>
      স্বাক্ষরিত উপজেলা নির্বাহী অফিসার<br/>জীবননগর, চুয়াডাঙ্গা।
    </div>
  );

  const ReportTitle = ({date}) => (
    <div style={{textAlign:"center",background:"#fff",padding:"12px 10px 6px",marginBottom:10,borderBottom:"2px solid #000"}}>
      <div style={{fontWeight:800,fontSize:17,color:"#000"}}>উপজেলা: জীবননগর</div>
      <div style={{fontWeight:700,fontSize:15,marginTop:3,color:"#000"}}>জ্বালানী তেলের দৈনিক রিপোর্ট</div>
      <div style={{marginTop:4,fontSize:13,color:"#000"}}>তারিখ: {fmtDate(date)}</div>
    </div>
  );

  if(!loaded) return <div style={{padding:40,textAlign:"center",fontFamily:"'Nikosh',sans-serif"}}>লোড হচ্ছে...</div>;

  return (
    <div style={{fontFamily:"'Nikosh',sans-serif",minHeight:"100vh",background:"#f5f5f5",color:"#000"}}>

      {/* ── Topbar ── */}
      <div style={{background:"#222",color:"#fff",padding:"13px 20px",display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:10}}>
        <div>
          <div style={{fontWeight:800,fontSize:18,fontFamily:"'Nikosh',sans-serif"}}>⛽ জ্বালানী তেলের দৈনিক রিপোর্ট</div>
          <div style={{fontSize:12,opacity:.75,fontFamily:"'Nikosh',sans-serif"}}>উপজেলা: জীবননগর, চুয়াডাঙ্গা</div>
        </div>
        <div style={{display:"flex",gap:8}}>
          {[["entry","📝 তথ্য প্রবেশ"],["history","📅 তারিখ ভিত্তিক"]].map(([v,l])=>(
            <button key={v} onClick={()=>setView(v)}
              style={{background:view===v?"#fff":"transparent",color:view===v?"#222":"#fff",border:view===v?"none":"1px solid rgba(255,255,255,.5)",borderRadius:5,padding:"7px 15px",cursor:"pointer",fontWeight:700,fontSize:13,fontFamily:"'Nikosh',sans-serif"}}>
              {l}
            </button>
          ))}
        </div>
      </div>

      {/* ── Entry view ── */}
      {view==="entry" && (
        <div style={{padding:"18px 16px"}}>
          {/* Controls */}
          <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:14,flexWrap:"wrap",background:"#fff",padding:"12px 16px",border:"1px solid #ccc"}}>
            <label style={{fontWeight:700,fontSize:14}}>📅 তারিখ:</label>
            <input type="date" value={selDate} onChange={e=>setSelDate(e.target.value)}
              style={{padding:"7px 10px",border:"1px solid #888",fontSize:14,cursor:"pointer",fontFamily:"'Nikosh',sans-serif"}}/>
            <div style={{fontWeight:600,color:"#000",fontSize:14}}>{fmtDate(selDate)}</div>
            <button onClick={handleSave}
              style={{background:"#222",color:"#fff",border:"none",padding:"7px 18px",fontSize:13,cursor:"pointer",fontWeight:700,fontFamily:"'Nikosh',sans-serif"}}>
              💾 সংরক্ষণ
            </button>
            {msg && <span style={{color:"#000",fontWeight:700,fontSize:14,border:"1px solid #000",padding:"3px 10px"}}>{msg}</span>}
          </div>

          <ReportTitle date={selDate}/>
          <ReportTable rowsArr={rows} editable={true}/>
          <Signature/>

          <div style={{display:"flex",gap:10,marginTop:16,flexWrap:"wrap",alignItems:"center"}}>
            <DlBar date={selDate} rowsArr={allData[selDate]||rows}/>
            <span style={{fontSize:12,color:"#555"}}>💡 <b>পূর্বের মজুদ</b> আগের দিন থেকে স্বয়ংক্রিয়। <b>গাঢ় বর্ডার</b> = সমাপনী মজুদ।</span>
          </div>
        </div>
      )}

      {/* ── History view ── */}
      {view==="history" && (
        <div style={{padding:"18px 16px"}}>
          <div style={{fontWeight:700,fontSize:16,marginBottom:12,color:"#000",borderBottom:"2px solid #000",paddingBottom:6}}>📅 সংরক্ষিত তারিখসমূহ</div>
          {savedDates.length===0 && <div style={{color:"#555"}}>কোনো তথ্য সংরক্ষিত নেই।</div>}
          <div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:18}}>
            {savedDates.map(d=>(
              <div key={d} onClick={()=>{setHistDate(d);setHistRows(allData[d]);}}
                style={{background:histDate===d?"#222":"#fff",color:histDate===d?"#fff":"#000",border:"1px solid #000",padding:"6px 13px",cursor:"pointer",display:"flex",alignItems:"center",gap:8,fontWeight:600,fontSize:13}}>
                {fmtDate(d)}
                <span onClick={e=>{e.stopPropagation();deleteDate(d);}}
                  style={{color:histDate===d?"#ddd":"#000",fontWeight:800,fontSize:16,marginLeft:2,cursor:"pointer"}}>×</span>
              </div>
            ))}
          </div>

          {histRows && (
            <div>
              <ReportTitle date={histDate}/>
              <ReportTable rowsArr={histRows} editable={false}/>
              <Signature/>
              <div style={{marginTop:14}}>
                <DlBar date={histDate} rowsArr={histRows}/>
              </div>
            </div>
          )}
        </div>
      )}

      <style>{`
        @import url('https://fonts.maateen.me/nikosh/font.css');
        * { box-sizing:border-box; }
        body { font-family:'Nikosh',sans-serif; }
        input:focus { outline:2px solid #000; }
        input, button, th, td { font-family:'Nikosh',sans-serif !important; }
      `}</style>
    </div>
  );
}
